def _turn_relation_tokens(value: Any) -> set[str]:
    tokens = {
        token.strip("._:/\\-")
        for token in re.findall(r"[A-Za-z0-9_.:/\\-]{4,}", str(value or "").casefold())
    }
    return {
        token
        for token in tokens
        if token and token not in _TURN_RELATION_STOPWORDS and not token.isdigit()
    }


def _task_outcome_feedback(prompt: str, prior_context: str) -> bool:
    """Identify result feedback tied to a distinctive definite reference from the prior task."""
    normalized = " ".join(str(prompt or "").strip().split())
    if not normalized or len(normalized.split()) > 48:
        return False
    shared_terms = _turn_relation_tokens(normalized).intersection(
        _turn_relation_tokens(prior_context)
    )
    if not shared_terms:
        return False
    definite_terms: set[str] = set()
    for match in re.finditer(
        r"\bthe\s+([a-z0-9][a-z0-9_.-]*(?:\s+[a-z0-9][a-z0-9_.-]*){0,3})",
        normalized,
        re.IGNORECASE,
    ):
        definite_terms.update(_turn_relation_tokens(match.group(1)))
    if not definite_terms.intersection(shared_terms):
        return False
    return bool(
        re.search(
            r"\b(?:blank|broken|empty|incorrect|inaccessible|invisible|missing|unresponsive|wrong|stuck)\b|"
            r"\b(?:crash(?:ed|es)?|fail(?:ed|s)?|hang(?:s|ing)?|froze|times?\s+out)\b|"
            r"\b(?:does\s+not|doesn't|did\s+not|didn't|will\s+not|won't|cannot|can't|not)\s+"
            r"(?:appear|display|finish|load|open|render|respond|run|show|start|work|working|visible)\b|"
            r"\b(?:is|are|was|were|looks?|seems?)\s+(?:still\s+)?not\b|"
            r"\b(?:i|we)\s+(?:do\s+not|don't|cannot|can't)\s+(?:see|find|observe|access)\b|"
            r"\b(?:is|are|was|were|looks?|seems?)\s+(?:now\s+|still\s+)?"
            r"(?:correct|fixed|open|rendered|responsive|running|visible|working)\b",
            normalized,
            re.IGNORECASE,
        )
    )


def _task_outcome_requires_repair(prompt: str, prior_context: str) -> bool:
    """Identify negative outcome feedback that requires continuing the prior task."""
    if not _task_outcome_feedback(prompt, prior_context):
        return False
    normalized = " ".join(str(prompt or "").strip().split())
    return bool(
        re.search(
            r"\b(?:blank|broken|empty|incorrect|inaccessible|invisible|missing|unresponsive|wrong|stuck)\b|"
            r"\b(?:crash(?:ed|es)?|fail(?:ed|s)?|hang(?:s|ing)?|froze|times?\s+out)\b|"
            r"\b(?:does\s+not|doesn't|did\s+not|didn't|will\s+not|won't|cannot|can't|not)\s+"
            r"(?:appear|display|finish|load|open|render|respond|run|show|start|work|working|visible)\b|"
            r"\b(?:is|are|was|were|looks?|seems?)\s+(?:still\s+)?not\b|"
            r"\b(?:i|we)\s+(?:do\s+not|don't|cannot|can't)\s+(?:see|find|observe|access)\b|"
            r"\b(?:is|are|was|were)\s+(?:now\s+|still\s+)?not\s+"
            r"(?:correct|fixed|open|rendered|responsive|running|visible|working)\b",
            normalized,
            re.IGNORECASE,
        )
    )


def _implicit_artifact_revision_request(prompt: str, target_paths: Sequence[str]) -> bool:
    """Bind a declarative revision only when it describes the sole prior text artifact."""
    normalized = " ".join(str(prompt or "").strip().split())
    if len(target_paths) != 1 or not normalized or len(normalized.split()) > 100:
        return False
    if "?" in normalized or re.match(
        r"^(?:new|separate|unrelated|different)\s+(?:question|request|task|topic)\b",
        normalized,
        re.IGNORECASE,
    ):
        return False
    pronoun_revision = bool(re.search(
        r"\b(?:it|this|that)\s+(?:should|needs?\s+to|must)\s+"
        r"(?:be|have|use|include|show|display|render|contain|support)\b",
        normalized,
        re.IGNORECASE,
    ))
    match = re.search(
        r"\bthe\s+(.{1,100}?)\s+(?:should|needs?\s+to|must)\s+"
        r"(?:be|have|use|include|show|display|render|contain|support)\b",
        normalized,
        re.IGNORECASE,
    )
    target = Path(target_paths[0])
    if not target.is_file() or target.suffix.casefold() not in {
        ".py", ".js", ".ts", ".html", ".css", ".json", ".md", ".txt", ".svg",
    }:
        return False
    named_files = re.findall(r"\b[\w.-]+\.(?:py|js|ts|html|css|json|md|txt|svg)\b", normalized, re.IGNORECASE)
    if named_files and any(name.casefold() != target.name.casefold() for name in named_files):
        return False
    if pronoun_revision:
        return True
    if match is None:
        try:
            with target.open("rb") as stream:
                content = stream.read(128 * 1024)
        except OSError:
            return False
        return b"\0" not in content and _task_outcome_requires_repair(
            normalized, content.decode("utf-8", errors="replace")
        )
    subject_terms = _turn_relation_tokens(match.group(1)) - {
        "each", "other", "existing", "current", "whole", "same", "more", "much",
    }
    if not subject_terms:
        return False
    if subject_terms.intersection({"file", "script", "page", "document", "output", "artifact", "code"}):
        return True
    try:
        with target.open("rb") as stream:
            content = stream.read(128 * 1024)
    except OSError:
        return False
    if b"\0" in content:
        return False
    content_text = content.decode("utf-8", errors="replace")
    content_terms = _turn_relation_tokens(content_text)
    return bool({term.removesuffix("s") for term in subject_terms}.intersection(
        {term.removesuffix("s") for term in content_terms}
    ))


def _unexecuted_tool_call_name(
    rendered_answer: Any, available_names: tuple[str, ...] = (),
) -> str:
    # Printed calls are evidence of a formatting failure, never executable input.
    rendered = re.sub(r"```.*?```", "", str(rendered_answer or ""), flags=re.DOTALL).strip()
    match = re.search(r"<function=([A-Za-z][A-Za-z0-9_]*)>", rendered)
    if match:
        return match.group(1)
    wrapper = re.search(r"<tool_call>\s*(.*?)\s*</tool_call>", rendered, re.DOTALL)
    candidate = wrapper.group(1) if wrapper else rendered
    with suppress(ValueError, TypeError):
        payload = json.loads(candidate)
        if isinstance(payload, list):
            payload = payload[0] if payload else None
        if isinstance(payload, dict):
            function = payload.get("function", payload)
            if isinstance(function, dict) and function.get("name") and (
                wrapper or "arguments" in function
            ):
                return str(function["name"])
    for name in available_names:
        if re.search(rf"<{re.escape(name)}(?:\s|>)", rendered):
            return name
    return "__unparsed__" if wrapper or "<tool_call>" in rendered else ""


def _diagnostic_failure_feedback(prompt: str, prior_context: str) -> bool:
    """Identify concrete diagnostics that belong to the preceding task."""
    normalized = str(prompt or "").strip()
    if not normalized or len(normalized) > 12_000 or not str(prior_context or "").strip():
        return False
    diagnostic_text = normalized
    if not re.search(r"\b(?:traceback|instead|but|actually|unexpectedly)\b", normalized, re.IGNORECASE):
        # Exception types in requested validation rules are not observed failures.
        diagnostic_text = re.sub(
            r"\b(?:raise|raising|throw|throwing)\s+(?:(?:a|an)\s+)?(?:[A-Za-z_]\w*(?:Error|Exception)|Exception)\b|"
            r"\breject\b[^.!?\n]{0,160}?\bwith\s+(?:(?:a|an)\s+)?(?:[A-Za-z_]\w*(?:Error|Exception)|Exception)\b",
            "", normalized, flags=re.IGNORECASE,
        )
    diagnostic = bool(
        re.search(
            r"\b(?:traceback|runtimeerror|exception|fatal|segmentation fault|cuda error|"
            r"module(?:notfound)?error|syntaxerror|typeerror|valueerror|keyerror|"
            r"attributeerror|permissionerror|time(?:d)?\s*out)\b|"
            r"\bfile\s+[\"'][^\"']+[\"']\s*,\s*line\s+\d+",
            diagnostic_text,
            re.IGNORECASE,
        )
    )
    if not diagnostic:
        return False
    shared_terms = _turn_relation_tokens(normalized).intersection(
        _turn_relation_tokens(prior_context)
    )
    prior_terms = _turn_relation_tokens(prior_context)
    for named_path in re.findall(r"\bFile\s+[\"']([^\"']+)[\"']", normalized, re.IGNORECASE):
        filename = re.split(r"[/\\]", named_path)[-1].rsplit(".", 1)[0]
        shared_terms.update(_turn_relation_tokens(re.sub(r"[-_.]+", " ", filename)).intersection(prior_terms))
    contextual_diagnostic = bool(
        re.match(
            r"^(?:this|that|it|the\s+(?:error|failure|traceback|command|script|task))\b",
            " ".join(normalized.split()),
            re.IGNORECASE,
        )
    )
    return bool(shared_terms or contextual_diagnostic)


def _independent_request_routing_prompt(prompt: str) -> str:
    normalized = " ".join(str(prompt or "").strip().split())
    match = re.match(
        r"^(?:new|separate|unrelated|different)\s+(?:question|request|task|topic)\b"
        r"\s*[:;,\-]?\s*(?P<body>.*)$",
        normalized,
        re.IGNORECASE,
    )
    if match is None:
        return normalized
    return str(match.group("body") or "").strip() or normalized


def _resolve_named_workspace_path(base: Any, workspace: Path, candidate: str) -> Path:
    """Resolve a workspace path without following its final symlink component."""
    normalized = base.normalize_workspace_text(candidate)
    translated_windows_path: Path | None = None
    if base.in_wsl() and base.WINDOWS_DRIVE_PATH_PATTERN.match(normalized):
        drive = normalized[0].lower()
        remainder = normalized[2:].replace("\\", "/").lstrip("/")
        translated_windows_path = Path("/mnt") / drive / remainder if remainder else Path("/mnt") / drive
    raw = translated_windows_path or Path(normalized).expanduser()
    unresolved = raw if translated_windows_path is not None or raw.is_absolute() else workspace / raw
    target = unresolved.parent.resolve() / unresolved.name
    if not target.is_relative_to(workspace.resolve()):
        raise ValueError(f"Path escapes workspace: {candidate}")
    return target


def _user_context_aliases(prompt: str) -> frozenset[str]:
    """Only the current user's prose may activate aliases; fenced examples remain data."""
    prose = " ".join(re.split(r"```[\s\S]*?```", str(prompt or ""))[::2])
    aliases: set[str] = set()
    if re.search(r"(?<![\w./\\-])qspace(?![\w-]|\.[A-Za-z0-9])", prose, re.IGNORECASE):
        aliases.add("qspace")
    if re.search(r"(?<![\w./\\-])qfiles(?![\w/\\-]|\.[A-Za-z0-9])", prose, re.IGNORECASE):
        aliases.add("qfiles")
    if re.search(r"(?<![\w./\\-])qfile(?![\w/\\-]|\.[A-Za-z0-9])", prose, re.IGNORECASE):
        aliases.add("qfile")
    return frozenset(aliases)


def _verified_created_alias_paths(evidence_items: Sequence[dict[str, Any]], workspace: Path) -> tuple[str, ...]:
    """Keep only files whose creation was verified by the current tool turn."""
    workspace_root = workspace.resolve()
    paths: set[str] = set()
    for evidence in evidence_items:
        if (
            not evidence.get("success")
            or evidence.get("tool") not in {"write_file", "write_files", "copy_path"}
            or "created_outputs" not in evidence.get("categories", ())
        ):
            continue
        for value in evidence.get("paths", ()):
            with suppress(OSError, ValueError):
                candidate = Path(str(value))
                target = candidate.resolve()
                if not candidate.is_symlink() and target.is_relative_to(workspace_root) and target.is_file():
                    paths.add(str(target))
    return tuple(sorted(paths, key=str.casefold))


def _verified_recent_alias_paths(
    base: Any,
    prompt: str,
    evidence_items: Sequence[dict[str, Any]],
    workspace: Path,
    inherited_paths: Sequence[str] = (),
) -> tuple[str, ...]:
    """Bind the latest turn to edited, explicitly discussed, or read local files."""
    root = workspace.resolve()

    def existing_files(values: Sequence[str]) -> tuple[str, ...]:
        paths: set[str] = set()
        for value in values:
            with suppress(OSError, ValueError):
                candidate = _resolve_named_workspace_path(base, workspace, str(value))
                if not candidate.is_symlink() and candidate.is_file():
                    target = candidate.resolve()
                    if target.is_relative_to(root):
                        paths.add(str(target))
        return tuple(sorted(paths, key=str.casefold))

    changed = existing_files([
        str(path)
        for item in evidence_items
        if item.get("success") and "changed_files" in item.get("categories", ())
        for path in item.get("paths", ())
    ])
    if changed:
        return changed
    discussed = existing_files(_explicit_file_reference_tokens(base, prompt))
    if discussed:
        return discussed
    read = existing_files([
        str(path)
        for item in evidence_items
        if item.get("success") and item.get("tool") in {"read_file", "read_file_snapshot"}
        for path in item.get("paths", ())
    ])
    return read or existing_files(inherited_paths)


def _resolve_user_context_aliases(
    prompt: str,
    workspace: Path,
    created_paths: Sequence[str],
) -> tuple[str, frozenset[str], str, str]:
    """Resolve user aliases from the immediately preceding relevant turn."""
    aliases = _user_context_aliases(prompt)
    qfile_path = ""
    bound_paths: list[str] = []
    if aliases.intersection({"qfile", "qfiles"}):
        for value in created_paths:
            candidate = Path(value)
            with suppress(OSError, ValueError):
                target = candidate.resolve()
                if not candidate.is_symlink() and target.is_relative_to(workspace.resolve()) and target.is_file():
                    bound_paths.append(str(target))
        if len(bound_paths) != len(created_paths):
            return prompt, aliases, "", "A recent file alias no longer names an existing file in this workspace. Please name the file(s)."
        if not bound_paths:
            if "qfile" in aliases:
                return prompt, aliases, "", "`qfile` is not uniquely bound. No recent file is available. Please name the file."
            return prompt, aliases, "", "`qfiles` has no recent file set. Please name the files."
        if len(bound_paths) > 32:
            return prompt, aliases, "", "The recent file set is too large for `qfiles`. Please name the relevant files."
    if "qfile" in aliases:
        if len(bound_paths) != 1:
            reason = (
                "No recent file is available in this workspace."
                if not bound_paths else "The latest relevant turn involved multiple files."
            )
            return prompt, aliases, "", f"`qfile` is not uniquely bound. {reason} Please name the file."
        qfile_path = bound_paths[0]

    parts = re.split(r"(```[\s\S]*?```)", prompt)
    relative_file = Path(qfile_path).relative_to(workspace.resolve()).as_posix() if qfile_path else ""
    relative_files = [Path(path).relative_to(workspace.resolve()).as_posix() for path in bound_paths]
    for index in range(0, len(parts), 2):
        prose = parts[index]
        if "qspace" in aliases:
            prose = re.sub(
                r"(?<![\w./\\-])qspace(?=[/\\])",
                workspace.resolve().as_posix(),
                prose,
                flags=re.IGNORECASE,
            )
            prose = re.sub(
                r"(?<![\w./\\-])(?:(?:the|my|our|this|current)\s+)?qspace(?![\w/\\-]|\.[A-Za-z0-9])",
                "the workspace",
                prose,
                flags=re.IGNORECASE,
            )
        if qfile_path:
            prose = re.sub(
                r"(?<![\w./\\-])qfile(?![\w/\\-]|\.[A-Za-z0-9])",
                f"`{relative_file}`",
                prose,
                flags=re.IGNORECASE,
            )
        if "qfiles" in aliases:
            prose = re.sub(
                r"(?<![\w./\\-])qfiles(?![\w/\\-]|\.[A-Za-z0-9])",
                ", ".join(f"`{path}`" for path in relative_files),
                prose,
                flags=re.IGNORECASE,
            )
        parts[index] = prose
    return "".join(parts), aliases, qfile_path, ""


def _expand_alias_tool_paths(
    name: str,
    arguments: dict[str, Any],
    workspace: Path,
    qfile_path: str,
    active_aliases: frozenset[str],
    qfiles_paths: Sequence[str] = (),
) -> dict[str, Any]:
    """Expand aliases only in filesystem path fields, never in content or commands."""
    if name not in {
        "list_files", "read_file", "read_file_snapshot", "search_text", "write_file",
        "write_files", "make_directory", "copy_path", "move_path", "delete_path",
        "apply_text_patch", "apply_text_patches", "apply_docx_text_patch",
        "apply_notebook_text_patch", "apply_spreadsheet_cell_patch",
    } or not active_aliases:
        return arguments

    def expand(value: Any) -> Any:
        if not isinstance(value, str):
            return value
        if "qfile" in active_aliases and value.casefold() == "qfile" and qfile_path:
            return qfile_path
        if "qfiles" in active_aliases and value.casefold() == "qfiles" and len(qfiles_paths) == 1:
            return qfiles_paths[0]
        if "qspace" in active_aliases:
            if value.casefold() == "qspace":
                return str(workspace.resolve())
            if re.match(r"^qspace[/\\]", value, re.IGNORECASE):
                return str(workspace.resolve() / value[7:])
        return value

    def expand_fields(item: dict[str, Any]) -> dict[str, Any]:
        updated = dict(item)
        for key in ("path", "source", "destination", "directory", "root", "cwd"):
            if key in updated:
                updated[key] = expand(updated[key])
        return updated

    updated = expand_fields(arguments)
    for key in ("files", "patches"):
        if isinstance(updated.get(key), list):
            updated[key] = [expand_fields(item) if isinstance(item, dict) else item for item in updated[key]]
    if isinstance(updated.get("paths"), list):
        paths: list[Any] = []
        for item in updated["paths"]:
            if (
                "qfiles" in active_aliases
                and isinstance(item, str)
                and item.casefold() == "qfiles"
            ):
                paths.extend(qfiles_paths)
            else:
                paths.append(expand(item))
        updated["paths"] = paths
    return updated


def _file_token_candidates(prompt: str) -> list[str]:
    # Apostrophes within words are not quote delimiters (workspace's, don't).
    pattern = re.compile(
        r"`([^`\r\n]+)`|\"([^\"\r\n]+)\"|(?<!\w)'([^'\r\n]+)'(?!\w)|"
        r"(?<!\w)([A-Za-z]:[A-Za-z0-9_ .\-\\/]+\.[A-Za-z0-9_]+|"
        r"[A-Za-z0-9_.\-\\/]+\.[A-Za-z0-9_]+)(?!\w)"
    )
    return list(dict.fromkeys(next(value for value in match.groups() if value is not None)
                             for match in pattern.finditer(prompt)))


def _normalize_adjacent_user_messages(messages: Sequence[dict[str, Any]]) -> list[dict[str, Any]]:
    """Merge adjacent textual user turns without inventing assistant/tool roles."""
    normalized: list[dict[str, Any]] = []
    for message in messages:
        current = dict(message)
        if (normalized and current.get("role") == normalized[-1].get("role") == "user"
                and isinstance(current.get("content"), str)
                and isinstance(normalized[-1].get("content"), str)
                and set(current) <= {"role", "content"} and set(normalized[-1]) <= {"role", "content"}):
            normalized[-1]["content"] += "\n\n" + current["content"]
        else:
            normalized.append(current)
    return normalized


def _explicit_file_reference_tokens(
    base: Any, prompt: str, *, for_creation: bool = False,
) -> list[str]:
    """Distinguish explicit paths, likely filenames, and source-only mentions."""
    tokens: list[str] = []
    named_candidates = re.findall(
        r"\b(?:file|script|document|path)\s+(?:named|called)\s+"
        r"(?:[`\"']([^`\"']+)[`\"']|([^\s,;:]+))",
        prompt,
        re.IGNORECASE,
    )
    prompt_without_urls = prompt
    for url in _extract_external_urls(prompt):
        prompt_without_urls = prompt_without_urls.replace(url, " ")
    candidates = _file_token_candidates(prompt_without_urls)
    candidates.extend(quoted or bare for quoted, bare in named_candidates)
    creation_verbs = list(re.finditer(
        r"\b(?:create|generate|write|save|make|draft|compose|produce|construct|design)\b",
        prompt,
        re.IGNORECASE,
    )) if for_creation else []
    clause_boundaries = list(re.finditer(
        r"[.!?;]\s+|\n+|(?<!\S)(?:then|but|however|instead),?\s+", prompt, re.IGNORECASE,
    ))
    for candidate in candidates:
        cleaned = str(candidate).strip().strip("`\"'").rstrip(".,;:")
        if not cleaned or re.match(r"^[a-z][a-z0-9+.-]*://", cleaned, re.IGNORECASE):
            continue
        normalized = cleaned.replace("\\", "/")
        named_file = re.search(
            rf"\b(?:file|script|document|path)\s+(?:named|called)\s+[`\"']?{re.escape(cleaned)}(?:\b|[`\"'])",
            prompt,
            re.IGNORECASE,
        )
        likely_suffix = re.fullmatch(r"\.[a-z][a-z0-9]{0,11}", Path(normalized).suffix, re.IGNORECASE)
        if not (
            base.is_explicit_absolute_path_text(cleaned)
            or "/" in normalized
            or likely_suffix is not None
            or named_file is not None
        ):
            continue
        eligible_mentions = []
        for occurrence in re.finditer(re.escape(cleaned), prompt, re.IGNORECASE):
            clause_start = max(
                (boundary.end() for boundary in clause_boundaries if boundary.end() <= occurrence.start()),
                default=0,
            )
            prefix = prompt[clause_start:occurrence.start()]
            explicit_destination = bool(re.search(
                r"\b(?:file|script|document|path|output)\s+(?:named|called|as)\s*[`\"']?$|"
                r"\b(?:filename|file\s+name)\s*[`\"']?$",
                prefix,
                re.IGNORECASE,
            ))
            technology_reference = bool(
                "/" not in normalized
                and not explicit_destination
                and not re.search(r"\b(?:local|our|workspace|project)\b", prefix, re.IGNORECASE)
                and (
                    re.search(
                        r"\b(?:library|framework|package|dependency|sdk|api)\b"
                        r".{0,64}\b(?:such\s+as|like|including|named|called)\s*$",
                        prefix,
                        re.IGNORECASE,
                    )
                    or re.search(
                        r"\b(?:use|using|with|via|import)\b.{0,64}"
                        r"\b(?:library|framework|package|dependency|sdk|api)\b.{0,64}$",
                        prefix,
                        re.IGNORECASE,
                    )
                    or (
                        re.search(r"\b(?:use|using|with|via|import)\b.{0,64}$", prefix, re.IGNORECASE)
                        and re.match(
                            r"\s+(?:library|framework|package|dependency|sdk|api)\b",
                            prompt[occurrence.end():],
                            re.IGNORECASE,
                        )
                    )
                )
            )
            if not technology_reference:
                eligible_mentions.append((occurrence, clause_start, explicit_destination))
        if not eligible_mentions:
            continue
        if for_creation:
            destination = False
            for occurrence, clause_start, explicit_destination in eligible_mentions:
                preceding = [
                    verb for verb in creation_verbs
                    if clause_start <= verb.start() and verb.end() <= occurrence.start()
                ]
                if not preceding:
                    continue
                if _semantic_action_is_negated(prompt[clause_start:occurrence.start()], preceding[-1].start() - clause_start):
                    continue
                between = prompt[preceding[-1].end():occurrence.start()]
                if explicit_destination or not re.search(
                    r"\b(?:based\s+on|use|using|with|via|such\s+as|like|from|"
                    r"read(?:s|ing)?|pars(?:e|es|ing)|inspect(?:s|ing)?|"
                    r"reference(?:s|d|ing)?|about|regarding|copy|run|verify|"
                    r"test|open|link(?:s|ing)?)\b",
                    between,
                    re.IGNORECASE,
                ):
                    destination = True
                    break
            if not destination:
                continue
        if cleaned not in tokens:
            tokens.append(cleaned)
    return tokens


def _creation_tool_name(prompt: str) -> str | None:
    semantic = _analyze_semantic_intent(prompt)
    if not semantic.requests("create"):
        return None
    if re.search(r"\.(?:docx?|xlsx?|xlsm|pptx?|pdf|png|jpe?g|zip|exe|gguf)\b", prompt, re.IGNORECASE):
        return None
    if re.search(
        r"\b(?:create|make|add|generate)\s+(?:(?:a|an|new|the)\s+)?(?:directory|folder)\b",
        prompt,
        re.IGNORECASE,
    ):
        return "make_directory"
    return "write_file"


